        if (iconBtn) iconBtn.textContent = p.icon;
        (p.flags || []).forEach(f => {
            const chip = document.querySelector('#roleFlagChips .role-chip[data-val="' + f + '"]');
            if (chip) chip.classList.add('on');
        });
        updateRolePromptPreview();
