    function _genUpdateStats(text) {
        const words = text.split(/\s+/).filter(Boolean).length;
        const tokens = Math.ceil(text.length / 4);
        const sections = (text.match(/^(#{1,4} |[A-Z][A-Za-z /&-]{2,40}:|\d+\. |<[a-z_]+>)/gm) || []).length;
        const placeholders = (text.match(/\[[^\]\n]{2,60}\]/g) || []).length;
        const set = (id, val) => {
            const el = $('#' + id);
            if (el) el.textContent = String(val);
        };
        set('genStatWords', words);
        set('genStatTokens', '~' + tokens);
        set('genStatSections', sections);
        set('genStatPlaceholders', placeholders);
    }

    function _genShowOutput(text) {
        _genState.lastOutput = text;
        const out = $('#genOutput');
        if (out) out.textContent = text;
        const actions = $('#genOutputActions');
        if (actions) actions.hidden = false;
        const count = $('#genTokenCount');
        if (count) count.textContent = '~' + Math.ceil(text.length / 4) + ' tokens · ' + text.length + ' chars';
        _genUpdateStats(text);
    }

    async function runGeneration() {
        const task = $('#genTaskInput')?.value?.trim();
        if (!task) {
            toast('Describe what the prompt should do first', 'warning');
            return;
        }
        const format = $('#genFormatSelect')?.value || 'any';
        const tone = $('#genToneSelect')?.value || '';
        const audience = $('#genAudienceInput')?.value?.trim() || '';
        const custom = $('#genCustomInstructions')?.value?.trim() || '';
        const model = $('#genModelSelect')?.value || 'any';
        const detail = _genState.detail;

        const sys = 'You are an expert prompt engineer. Write ONE complete, production-ready prompt that a user can paste directly into an AI assistant. Output ONLY the prompt text itself — no preamble, no explanation, no markdown code fences around the whole prompt. Follow every structural and technique requirement exactly.';

        let req = 'Write a prompt for this task:\n' + task;
        req += '\n\nPrompt domain: ' + _genState.type;

        if (_genState.framework !== 'auto' && _genFrameworkGuides[_genState.framework]) {
            req += '\n\nFramework requirement:\n' + _genFrameworkGuides[_genState.framework];
        } else {
            req += '\n\nFramework: choose the best-fit prompt structure for the task.';
        }

        if (_genState.techniques.size) {
            req += '\n\nApply these prompt-engineering techniques:';
            _genState.techniques.forEach(t => {
                if (_genTechniqueGuides[t]) req += '\n- ' + _genTechniqueGuides[t];
            });
        }

        if (format !== 'any') req += '\n\nThe prompt must instruct the AI to deliver its answer as: ' + format + '.';
        if (tone) req += '\nThe prompt should set this tone for the answer: ' + tone + '.';
        if (audience) req += '\nTarget audience of the final answer: ' + audience + '.';
        if (model !== 'any') req += '\nOptimise the prompt wording and structure for ' + model + '.';

        if (_genState.creativity === 'precise') {
            req += '\nThe prompt should demand precise, factual, deterministic answers — no creative flourish.';
        } else if (_genState.creativity === 'creative') {
            req += '\nThe prompt should encourage creative, novel, original answers.';
        }

        if (detail === 'concise') {
            req += '\nKeep the prompt itself short and direct — a single tight block plus output instructions.';
        } else if (detail === 'detailed') {
            req += '\nMake the prompt itself thorough: role, context, step-by-step instructions, constraints, output format, and a quality bar.';
        } else {
            req += '\nUse a balanced prompt structure: role, task, key constraints, output format.';
        }

        if (custom) req += '\n\nAdditional user requirements (must be honoured):\n' + custom;

        const out = await callAI(sys, req, detail === 'detailed' ? 2000 : 1100);
        _genShowOutput(out);
    }

    function initGenWorkspace() {
        const ws = $('#genWorkspace');
        if (!ws) return;

        // Single-select chip groups
        const wireChips = (containerId, stateKey) => {
            $$('#' + containerId + ' .gen-chip').forEach(btn => {
                btn.addEventListener('click', () => {
                    $$('#' + containerId + ' .gen-chip').forEach(b => {
                        b.classList.remove('active');
                        b.setAttribute('aria-pressed', 'false');
                    });
                    btn.classList.add('active');
                    btn.setAttribute('aria-pressed', 'true');
                    _genState[stateKey] = btn.dataset.value;
                });
            });
        };
        wireChips('genTypeChips', 'type');
        wireChips('genDetailChips', 'detail');
        wireChips('genCreativityChips', 'creativity');

        // Framework rail: single-select
        $$('#genFrameworks .opt-fw-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                $$('#genFrameworks .opt-fw-btn').forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                _genState.framework = btn.dataset.fw;
            });
        });

        // Techniques: multi-select toggle
        $$('#genTechniques .opt-tech-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const t = btn.dataset.tech;
                if (_genState.techniques.has(t)) {
                    _genState.techniques.delete(t);
                    btn.classList.remove('active');
                } else {
                    _genState.techniques.add(t);
                    btn.classList.add('active');
                }
            });
        });
        $('#genSelectAllTechBtn')?.addEventListener('click', () => {
            $$('#genTechniques .opt-tech-btn').forEach(btn => {
                _genState.techniques.add(btn.dataset.tech);
                btn.classList.add('active');
            });
        });
        $('#genClearTechBtn')?.addEventListener('click', () => {
            _genState.techniques.clear();
            $$('#genTechniques .opt-tech-btn').forEach(btn => btn.classList.remove('active'));
        });

        const runWithSpinner = async () => {
            const btn = $('#genRunBtn');
            if (btn) {
                btn.disabled = true;
                btn.innerHTML = '<span class="material-symbols-outlined" style="animation:spin 1s linear infinite">progress_activity</span> Generating...';
            }
            try {
                await runGeneration();
            } catch (err) {
                toast(err.message || 'Generation failed', 'error');
            } finally {
                if (btn) {
                    btn.disabled = false;
                    btn.innerHTML = '<span class="material-symbols-outlined">bolt</span> Generate';
                }
            }
        };
        $('#genRunBtn')?.addEventListener('click', runWithSpinner);
        $('#genRegenBtn')?.addEventListener('click', runWithSpinner);

        $('#genCopyBtn')?.addEventListener('click', async () => {
            if (!_genState.lastOutput) return;
            const ok = await copyToClipboard(_genState.lastOutput);
            if (ok) toast('Generated prompt copied', 'success');
        });
        $('#genToOptimizerBtn')?.addEventListener('click', () => {
            if (!_genState.lastOutput) {
                toast('Generate a prompt first', 'warning');
                return;
            }
            closeGenWorkspace();
            window.openOptimizerWorkspace();
            const input = $('#optPromptInput');
            if (input) input.value = _genState.lastOutput;
        });
        $('#genSaveBtn')?.addEventListener('click', async () => {
            const text = _genState.lastOutput;
            if (!text) {
                toast('Generate a prompt first', 'warning');
                return;
            }
            const task = $('#genTaskInput')?.value?.trim() || '';
            const title = (task.split(' ').slice(0, 6).join(' ') || 'Generated prompt') + ' (generated)';
            try {
                const result = await api('/prompts', {
                    method: 'POST',
                    body: {
                        title,
                        content: text,
                        description: 'Created via Prompt Generator workspace',
                        categories: 'Prompt Engineering',
                        tags: 'generated'
                    }
                });
                await loadPrompts();
                await loadFilterOptions();
                toast('Saved: ' + title, 'success');
                closeGenWorkspace();
                if (result?.id) setTimeout(() => openDetail(result.id), 200);
            } catch {
                toast('Could not save', 'error');
            }
        });
        $('#closeGenBtn')?.addEventListener('click', closeGenWorkspace);
        ws.addEventListener('keydown', e => {
            if (e.key === 'Escape') closeGenWorkspace();
        });
    }

    /* ============================================================================
       WORKSPACES LAUNCHER
       ============================================================================ */

    /* Last three tools opened, most recent first. */
    function _launcherRecentList() {
        try {
            const raw = JSON.parse(localStorage.getItem('pl_ws_recent') || '[]');
            return Array.isArray(raw) ? raw : [];
        } catch (e) {
            return [];
        }
    }

    function _recordLauncherRecent(fn) {
        if (!fn) return;
        const next = [fn, ..._launcherRecentList().filter(x => x !== fn)].slice(0, 3);
        try {
            localStorage.setItem('pl_ws_recent', JSON.stringify(next));
        } catch (e) { /* quota or private mode - recents are non-essential */ }
    }

    function _renderLauncherRecent() {
        const wrap = $('#launcherRecent');
        const row = $('#launcherRecentRow');
        if (!wrap || !row) return;
        const cards = _launcherRecentList()
            .map(fn => $(`#launcherGrid .launcher-card[data-open="${fn}"]`))
            .filter(Boolean)
            .slice(0, 3);
        if (!cards.length) {
            wrap.hidden = true;
            row.innerHTML = '';
            return;
        }
        row.innerHTML = cards.map(c => {
            const icon = c.querySelector('.launcher-card-icon')?.textContent.trim() || 'grid_view';
            const title = c.querySelector('.launcher-card-title')?.textContent.trim() || '';
            const isPro = c.dataset.premium === 'true';
            return `<button class="launcher-recent-card" data-open="${escapeAttr(c.dataset.open)}" data-premium="${isPro}">
            <span class="material-symbols-outlined">${escapeHtml(icon)}</span>
            <span class="launcher-recent-title">${escapeHtml(title)}</span>
            ${isPro ? '<span class="launcher-card-pro">PRO</span>' : ''}
          </button>`;
        }).join('');
        wrap.hidden = false;
    }

    window.openWorkspacesLauncher = function() {
        $('#workspacesLauncher')?.classList.add('open');
        $$('.nav-item[data-view]').forEach(el =>
            el.classList.toggle('active', el.dataset.view === 'workspaces'));
        _renderLauncherRecent();
        const s = $('#launcherSearch');
        if (s) {
            s.value = '';
            s.dispatchEvent(new Event('input'));
            setTimeout(() => s.focus(), 50);
        }
    };

    function closeWorkspacesLauncher() {
        $('#workspacesLauncher')?.classList.remove('open');
        $$('.nav-item[data-view]').forEach(el =>
            el.classList.toggle('active', el.dataset.view === 'library'));
    }

    function initWorkspacesLauncher() {
        const ws = $('#workspacesLauncher');
        if (!ws) return;

        $$('#launcherGrid .launcher-card').forEach(card => {
            card.addEventListener('click', () => {
                const locked = card.dataset.premium === 'true' && !state.isPremium;
                if (locked) {
                    showPremiumModal();
                    return;
                }
                const fn = card.dataset.open;
                _recordLauncherRecent(fn);
                closeWorkspacesLauncher();
                if (fn && typeof window[fn] === 'function') window[fn]();
            });
        });

        // Recents row is rendered on open, so delegate rather than bind per card.
        $('#launcherRecentRow')?.addEventListener('click', (e) => {
            const btn = e.target.closest('.launcher-recent-card');
            if (!btn) return;
            if (btn.dataset.premium === 'true' && !state.isPremium) {
                showPremiumModal();
                return;
            }
            const fn = btn.dataset.open;
            _recordLauncherRecent(fn);
            closeWorkspacesLauncher();
            if (fn && typeof window[fn] === 'function') window[fn]();
        });

        $('#closeLauncherBtn')?.addEventListener('click', closeWorkspacesLauncher);
        ws.addEventListener('keydown', e => {
            if (e.key === 'Escape') closeWorkspacesLauncher();
        });

        // Search filter — hides cards, then any group left empty
        $('#launcherSearch')?.addEventListener('input', e => {
            const q = e.target.value.trim().toLowerCase();
            let anyVisible = false;
            $$('#launcherGrid .launcher-card').forEach(card => {
                const show = !q || card.textContent.toLowerCase().includes(q);
                card.style.display = show ? '' : 'none';
                if (show) anyVisible = true;
            });
            $$('#launcherGrid .launcher-group').forEach(group => {
                const has = [...group.querySelectorAll('.launcher-card')].some(cd => cd.style.display !== 'none');
                group.style.display = has ? '' : 'none';
            });
            const empty = $('#launcherEmpty');
            if (empty) empty.hidden = anyVisible;
            // Recents are not part of the result set - hide them while searching.
            // Clearing the inline style hands control back to the [hidden] rule.
            const recent = $('#launcherRecent');
            if (recent) recent.style.display = q ? 'none' : '';
        });
    }

