    function closeDashboardWorkspace() {
        $('#dashboardWorkspace')?.classList.remove('open');
        $$('.nav-item[data-view]').forEach(el =>
            el.classList.toggle('active', el.dataset.view === 'library'));
    }

    function _refreshDashboard() {
        const total = state.prompts.length;
        const favs = state.prompts.filter(p => p.is_favorite).length;
        const cats = state.filters?.categories?.length || 0;
        const tags = state.filters?.tags?.length || 0;

        const setText = (id, val) => {
            const el = $('#' + id);
            if (el) el.textContent = val;
        };
        setText('dashStatPrompts', total);
        setText('dashStatFavs', favs);
        setText('dashStatCategories', cats);
        setText('dashStatTags', tags);

        const listEl = $('#dashRecentList');
        if (!listEl) return;
        const recent = state.prompts
            .slice()
            .sort((a, b) => (b.updated_at || '').localeCompare(a.updated_at || ''))
            .slice(0, 6);

        if (!recent.length) {
            listEl.innerHTML = '<div class="dash-empty-hint">No prompts yet — create your first one from the Library.</div>';
            return;
        }
        listEl.innerHTML = recent.map(p => `
      <button class="dash-recent-item" data-id="${p.id}">
        <span class="dash-recent-title">${escapeHtml(p.title || 'Untitled')}</span>
        <span class="dash-recent-meta">${escapeHtml((p.categories || [])[0] || '')}</span>
      </button>`).join('');

        $$('#dashRecentList .dash-recent-item').forEach(btn => {
            btn.addEventListener('click', () => {
                closeDashboardWorkspace();
                openDetail(Number(btn.dataset.id));
            });
        });
    }

    function initDashboardWorkspace() {
        const ws = $('#dashboardWorkspace');
        if (!ws) return;

        $$('#dashboardWorkspace .dash-quick-tile[data-open]').forEach(btn => {
            btn.addEventListener('click', () => {
                const fn = btn.dataset.open;
                closeDashboardWorkspace();
                if (fn && typeof window[fn] === 'function') window[fn]();
            });
        });
        $('#dashSeeAllBtn')?.addEventListener('click', () => {
            closeDashboardWorkspace();
            window.openWorkspacesLauncher();
        });
        $('#dashGoLibraryBtn')?.addEventListener('click', () => {
            closeDashboardWorkspace();
            setView('library');
        });
        $('#closeDashboardBtn')?.addEventListener('click', closeDashboardWorkspace);
        ws.addEventListener('keydown', e => {
            if (e.key === 'Escape') closeDashboardWorkspace();
        });
    }

    /* ============================================================================
       WORKSPACE: Batch Runner
       data-view="batch" | openBatchWorkspace() | initBatchWorkspace()
       Runs one prompt across many input rows via callAI, one row at a time.
       ============================================================================ */

    const BR_MAX_ROWS = 50;
    const BR_WARN_ROWS = 25;
    const BR_SYSTEM = 'Execute the prompt exactly as written. Return only the result, with no preamble or commentary.';
    const BR_TUTORIAL_KEY = 'pl_br_tutorial_seen';
    const BR_EXAMPLE_SOURCE = 'Write a short, punchy product description for [[product]], aimed at [[audience]].';
    const BR_EXAMPLE_ROWS = 'product,audience\n' +
        'Wireless earbuds,Commuters who lose things\n' +
        'Standing desk,Remote workers with bad posture\n' +
        'Reusable water bottle,Gym-goers who forget theirs';

    let _brVars = [];
    let _brRows = [];
    let _brResults = [];
    let _brRunning = false;
    let _brCancel = false;

    function _brSubstitute(text, values) {
        Object.keys(values).forEach(name => {
            const val = values[name];
            if (val === undefined || val === null) return;
            ['[[' + name + ']]', '{{' + name + '}}', '((' + name + '))'].forEach(tok => {
                text = text.split(tok).join(val);
            });
        });
        return text;
    }

    // Minimal CSV field splitter - handles quoted cells and escaped quotes.
    function _brSplitCsv(line) {
        const out = [];
        let cur = '';
        let quoted = false;
        for (let i = 0; i < line.length; i++) {
            const ch = line[i];
            if (ch === '"') {
                if (quoted && line[i + 1] === '"') {
                    cur += '"';
                    i++;
                } else {
                    quoted = !quoted;
                }
            } else if (ch === ',' && !quoted) {
                out.push(cur);
                cur = '';
            } else {
                cur += ch;
            }
        }
        out.push(cur);
        return out.map(s => s.trim());
    }

    // A first line naming every detected variable makes the block CSV.
    // Otherwise one line = one value for the single variable, or one raw input.
    function _brParseRows(raw, vars) {
        const lines = (raw || '').split(/\r?\n/).map(l => l.trim()).filter(Boolean);
        if (!lines.length) return [];
        if (vars.length) {
            const header = _brSplitCsv(lines[0]);
            const isHeader = header.length === vars.length && header.every(h => vars.includes(h));
            if (isHeader) {
                return lines.slice(1).map(l => {
                    const cells = _brSplitCsv(l);
                    const row = {};
                    header.forEach((h, i) => { row[h] = cells[i] || ''; });
                    return row;
                });
            }
            const only = vars[0];
            return lines.map(l => ({ [only]: l }));
        }
        return lines.map(l => ({ __input: l }));
    }

    function _brResolved(row) {
        const src = $('#brSource')?.value || '';
        if (row.__input !== undefined) {
            return src.trim() + '\n\n' + row.__input;
        }
        return _brSubstitute(src, row);
    }

    function _brSyncSource() {
        const src = $('#brSource')?.value || '';
        _brVars = detectVariables(src);
        const chip = $('#brVarChip');
        if (chip) {
            chip.textContent = _brVars.length;
            chip.title = _brVars.length ? _brVars.join(', ') : 'No variables detected';
        }
        const hint = $('#brModeHint');
        if (hint) {
            if (!src.trim()) hint.textContent = 'Pick a prompt or paste one to begin.';
            else if (!_brVars.length) hint.textContent = 'No variables found - each line is appended to the prompt as its input.';
            else if (_brVars.length === 1) hint.textContent = `One variable (${_brVars[0]}) - each line fills it.`;
            else hint.textContent = `${_brVars.length} variables - first line must be a CSV header: ${_brVars.join(', ')}`;
        }
        _brSyncRows();
    }

    function _brSyncRows() {
        const raw = $('#brRows')?.value || '';
        _brRows = _brParseRows(raw, _brVars);
        let capped = false;
        if (_brRows.length > BR_MAX_ROWS) {
            _brRows = _brRows.slice(0, BR_MAX_ROWS);
            capped = true;
        }
        const tokens = _brRows.reduce((sum, r) => sum + _wsEstTokens(_brResolved(r)), 0);
        const stat = $('#brStat');
        if (stat) {
            const parts = [`${_brRows.length} row${_brRows.length === 1 ? '' : 's'}`];
            if (_brRows.length) parts.push(`~${tokens.toLocaleString()} input tokens`);
            const mdl = COST_MODELS[Number($('#brModel')?.value || 0)];
            if (mdl && _brRows.length) {
                const cost = (tokens / 1e6) * mdl.inPM + (_brRows.length * 600 / 1e6) * mdl.outPM;
                parts.push(`~$${cost.toFixed(cost < 1 ? 3 : 2)} est.`);
            }
            stat.textContent = parts.join('  ·  ');
        }
        const warn = $('#brWarn');
        if (warn) {
            if (capped) {
                warn.textContent = `Capped at ${BR_MAX_ROWS} rows - the rest were ignored.`;
                warn.hidden = false;
            } else if (_brRows.length > BR_WARN_ROWS) {
                warn.textContent = `${_brRows.length} rows means ${_brRows.length} API calls. Check the estimate before running.`;
                warn.hidden = false;
            } else {
                warn.hidden = true;
            }
        }
        const runBtn = $('#brRunBtn');
        if (runBtn) runBtn.disabled = _brRunning || !_brRows.length;
    }

    function _brRenderResults() {
        const body = $('#brResultsBody');
        const wrap = $('#brResultsWrap');
        const empty = $('#brResultsEmpty');
        if (!body || !wrap || !empty) return;
        if (!_brResults.length) {
            wrap.hidden = true;
            empty.hidden = false;
            return;
        }
        wrap.hidden = false;
        empty.hidden = true;
        body.innerHTML = _brResults.map((r, i) => {
            const row = _brRows[i] || {};
            const label = row.__input !== undefined
                ? row.__input
                : Object.keys(row).map(k => `${k}: ${row[k]}`).join(', ');
            const status = r.status === 'done' ? '<span class="br-pill ok">done</span>'
                : r.status === 'error' ? '<span class="br-pill err">failed</span>'
                : r.status === 'running' ? '<span class="br-pill run">running</span>'
                : '<span class="br-pill">queued</span>';
            const save = r.status === 'done'
                ? `<button class="btn btn-ghost btn-sm" onclick="window.PL_brSaveRow(${i})">Save</button>`
                : '';
            return `<tr>
        <td class="br-idx">${i + 1}</td>
        <td class="br-in" title="${escapeAttr(label)}">${escapeHtml(label.slice(0, 90))}</td>
        <td>${status}</td>
        <td class="br-out">${escapeHtml(r.output || '')}</td>
        <td class="br-row-actions">${save}</td>
      </tr>`;
        }).join('');
        const done = _brResults.filter(r => r.status === 'done').length;
        const failed = _brResults.filter(r => r.status === 'error').length;
        const prog = $('#brProgress');
        if (prog) prog.textContent = `${done} done${failed ? `, ${failed} failed` : ''} of ${_brResults.length}`;
    }

    async function _brRun() {
        if (!state.isPremium) {
            showPremiumModal();
            return;
        }
        if (_brRunning) return;
        _brSyncRows();
        if (!_brRows.length) {
            toast('Add some input rows first', 'warning');
            return;
        }
        if (!($('#brSource')?.value || '').trim()) {
            toast('Pick or paste a prompt first', 'warning');
            return;
        }
        _brRunning = true;
        _brCancel = false;
        _brResults = _brRows.map(() => ({ status: 'queued', output: '' }));
        _brRenderResults();
        $('#brRunBtn').disabled = true;
        $('#brStopBtn').hidden = false;

        for (let i = 0; i < _brRows.length; i++) {
            if (_brCancel) {
                _brResults[i] = { status: 'error', output: 'Cancelled' };
                continue;
            }
            _brResults[i] = { status: 'running', output: '' };
            _brRenderResults();
            try {
                const out = await callAI(BR_SYSTEM, _brResolved(_brRows[i]), 1200);
                _brResults[i] = { status: 'done', output: (out || '').trim() };
            } catch (e) {
                _brResults[i] = { status: 'error', output: (e && e.message) || 'Request failed' };
            }
            _brRenderResults();
        }

        _brRunning = false;
        $('#brStopBtn').hidden = true;
        _brSyncRows();
        _brRenderResults();
        _brPersist();
        const failed = _brResults.filter(r => r.status === 'error').length;
        if (_brCancel) toast('Batch stopped', 'warning');
        else if (failed) toast(`Finished with ${failed} failed`, 'warning');
        else toast('Batch complete', 'success');
    }

    function _brCsv() {
        const cell = (s) => '"' + String(s == null ? '' : s).replace(/"/g, '""') + '"';
        const cols = _brVars.length ? _brVars : ['input'];
        const head = ['#', ...cols, 'status', 'output'].map(cell).join(',');
        const body = _brResults.map((r, i) => {
            const row = _brRows[i] || {};
            const vals = _brVars.length ? _brVars.map(v => row[v]) : [row.__input];
            return [i + 1, ...vals, r.status, r.output].map(cell).join(',');
        });
        return [head, ...body].join('\n');
    }

    function _brPersist() {
        try {
            localStorage.setItem('pl_br_last', JSON.stringify({
                source: $('#brSource')?.value || '',
                rows: $('#brRows')?.value || ''
            }));
        } catch (e) { /* non-essential */ }
    }

    function _brRestore() {
        try {
            const saved = JSON.parse(localStorage.getItem('pl_br_last') || 'null');
            if (!saved) return;
            if ($('#brSource') && saved.source) $('#brSource').value = saved.source;
            if ($('#brRows') && saved.rows) $('#brRows').value = saved.rows;
        } catch (e) { /* ignore malformed */ }
    }

    // Fills the form with a worked example so a new user sees the CSV-header
    // convention in action rather than guessing it from the placeholder text.
    function _brLoadExample() {
        if ($('#brSource')) $('#brSource').value = BR_EXAMPLE_SOURCE;
        if ($('#brRows')) $('#brRows').value = BR_EXAMPLE_ROWS;
        _brSyncSource();
        toast('Example loaded', 'success');
    }

    // One-time tutorial card: auto-shown the first time Batch Runner opens,
    // manually replayable afterwards via the header help button.
    function _brShowTutorial() {
        const el = $('#brTutorial');
        if (el) el.hidden = false;
    }

    function _brHideTutorial() {
        const el = $('#brTutorial');
        if (el) el.hidden = true;
        try { localStorage.setItem(BR_TUTORIAL_KEY, '1'); } catch (e) { /* non-essential */ }
    }

    window.PL_brSaveRow = async function(i) {
        const r = _brResults[i];
        if (!r || r.status !== 'done' || !r.output.trim()) return;
        const picked = _wsPickedPrompt('#brPicker');
        const title = ((picked?.title || 'Batch output') + ` (row ${i + 1})`).slice(0, 120);
        try {
            const result = await api('/prompts', {
                method: 'POST',
                body: {
                    title,
                    content: r.output,
                    description: 'Generated by Batch Runner',
                    tags: 'batch-runner'
                }
            });
            await loadPrompts();
            await loadFilterOptions();
            toast('Saved: ' + title, 'success');
            if (result?.id) {
                closeBatchWorkspace();
                setTimeout(() => openDetail(result.id), 200);
            }
        } catch {
            toast('Could not save', 'error');
        }
    };

    window.openBatchWorkspace = function() {
        if (!state.isPremium) {
            showPremiumModal();
            return;
        }
        const ws = $('#batchWorkspace');
        if (!ws) return;
        ws.classList.add('open');
        document.body.style.overflow = 'hidden';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'batch'));
        _wsFillPromptPicker('#brPicker');
        _brRestore();
        _brSyncSource();
        _brRenderResults();
        try {
            if (!localStorage.getItem(BR_TUTORIAL_KEY)) _brShowTutorial();
        } catch (e) { /* non-essential */ }
    };

    function closeBatchWorkspace() {
        $('#batchWorkspace')?.classList.remove('open');
        document.body.style.overflow = '';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'library'));
    }

    function initBatchWorkspace() {
        const ws = $('#batchWorkspace');
        if (!ws) return;

        const modelSel = $('#brModel');
        if (modelSel && !modelSel.options.length) {
            modelSel.innerHTML = COST_MODELS
                .map((m, i) => `<option value="${i}">${escapeHtml(m.name)}</option>`).join('');
        }

        $('#closeBatchBtn')?.addEventListener('click', closeBatchWorkspace);
        $('#brHelpBtn')?.addEventListener('click', _brShowTutorial);
        $('#brExampleBtn')?.addEventListener('click', _brLoadExample);
        $('#brTutorialExampleBtn')?.addEventListener('click', () => { _brLoadExample(); _brHideTutorial(); });
        $('#brTutorialGotItBtn')?.addEventListener('click', _brHideTutorial);
        $('#brSource')?.addEventListener('input', _brSyncSource);
        $('#brRows')?.addEventListener('input', _brSyncRows);
        $('#brModel')?.addEventListener('change', _brSyncRows);

        $('#brPicker')?.addEventListener('change', () => {
            const p = _wsPickedPrompt('#brPicker');
            if (!p) return;
            const src = $('#brSource');
            if (src) {
                src.value = p.content || '';
                _brSyncSource();
            }
        });

        $('#brRunBtn')?.addEventListener('click', _brRun);
        $('#brStopBtn')?.addEventListener('click', () => {
            _brCancel = true;
            toast('Stopping after the current row...', 'warning');
        });

        $('#brClearBtn')?.addEventListener('click', () => {
            if (_brRunning) return;
            if ($('#brRows')) $('#brRows').value = '';
            _brResults = [];
            _brSyncRows();
            _brRenderResults();
            _brPersist();
        });

        $('#brCopyBtn')?.addEventListener('click', async () => {
            const done = _brResults.filter(r => r.status === 'done');
            if (!done.length) {
                toast('Nothing to copy yet', 'warning');
                return;
            }
            const text = done.map((r, i) => `--- Row ${i + 1} ---\n${r.output}`).join('\n\n');
            if (await copyToClipboard(text)) toast('All outputs copied', 'success');
        });

        $('#brExportBtn')?.addEventListener('click', async () => {
            if (!_brResults.length) {
                toast('Run a batch first', 'warning');
                return;
            }
            if (await copyToClipboard(_brCsv())) toast('CSV copied to clipboard', 'success');
        });

        ws.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && !_brRunning) closeBatchWorkspace();
        });
    }

    /* ============================================================================
       TAXONOMY STUDIO
       data-view="taxonomy" | openTaxonomyWorkspace() | initTaxonomyWorkspace()
       ============================================================================ */

    let _taxState = { domains: [], selectedType: null, selectedId: null, tagPickerOpen: false, tagPickerQuery: '', tagPickerSelection: [] };

    async function _taxLoadTree() {
        const list = $('#taxTreeList');
        if (list) list.innerHTML = '<p class="hint">Loading…</p>';
        try {
            _taxState.domains = await api('/taxonomy');
            _taxRenderTree();
        } catch {
            if (list) list.innerHTML = '<p class="hint">Couldn\'t load taxonomy — <a href="#" id="taxRetryLink">retry</a></p>';
            $('#taxRetryLink')?.addEventListener('click', (e) => { e.preventDefault(); _taxLoadTree(); });
        }
    }

    function _taxRenderTree() {
        const list = $('#taxTreeList');
        if (!list) return;
        if (!_taxState.domains.length) {
            list.innerHTML = '<p class="hint">No domains yet — add one to get started.</p>';
            return;
        }
        list.innerHTML = _taxState.domains.map(d => `
      <div class="tax-domain" data-domain-id="${d.id}">
        <div class="tax-domain-row ${_taxState.selectedType === 'domain' && _taxState.selectedId === d.id ? 'active' : ''}" data-select-domain="${d.id}">
          <span class="material-symbols-outlined tax-domain-icon">folder</span>
          <span class="tax-node-name">${escapeHtml(d.name)}</span>
          <span class="tax-node-count">${d.use_cases.length}</span>
          <button class="folder-mini-btn" data-tax-rename-domain="${d.id}" title="Rename"><span class="material-symbols-outlined">edit</span></button>
          <button class="folder-mini-btn danger" data-tax-delete-domain="${d.id}" title="Delete"><span class="material-symbols-outlined">delete</span></button>
          <button class="folder-mini-btn" data-tax-add-usecase="${d.id}" title="Add use-case"><span class="material-symbols-outlined">add</span></button>
        </div>
        <div class="tax-usecase-list">
          ${d.use_cases.length ? d.use_cases.map(u => `
            <div class="tax-usecase-row ${_taxState.selectedType === 'usecase' && _taxState.selectedId === u.id ? 'active' : ''}" data-select-usecase="${u.id}">
              <span class="material-symbols-outlined tax-usecase-icon">label</span>
              <span class="tax-node-name">${escapeHtml(u.name)}</span>
              <button class="folder-mini-btn" data-tax-rename-usecase="${u.id}" title="Rename"><span class="material-symbols-outlined">edit</span></button>
              <button class="folder-mini-btn danger" data-tax-delete-usecase="${u.id}" title="Delete"><span class="material-symbols-outlined">delete</span></button>
            </div>`).join('') : '<div class="tax-usecase-empty hint">No use-cases yet</div>'}
        </div>
      </div>`).join('');
    }

    async function _taxSelectNode(type, id) {
        _taxState.selectedType = type;
        _taxState.selectedId = id;
        _taxState.tagPickerOpen = false;
        _taxRenderTree();
        await _taxRenderDetail();
    }

    async function _taxRenderDetail() {
        const detail = $('#taxDetail');
        if (!detail) return;
        if (!_taxState.selectedType) {
            detail.innerHTML = '<div class="tax-detail-empty hint">Select a domain or use-case to see details.</div>';
            return;
        }
        if (_taxState.selectedType === 'domain') {
            const d = _taxState.domains.find(x => x.id === _taxState.selectedId);
            if (!d) return;
            detail.innerHTML = `
          <h3 class="tax-detail-title">${escapeHtml(d.name)}</h3>
          <p class="hint">${d.use_cases.length} use-case${d.use_cases.length !== 1 ? 's' : ''} in this domain.</p>`;
            return;
        }
        let uc = null, parentDomain = null;
        for (const d of _taxState.domains) {
            const found = d.use_cases.find(u => u.id === _taxState.selectedId);
            if (found) { uc = found; parentDomain = d; break; }
        }
        if (!uc) return;
        detail.innerHTML = `
      <h3 class="tax-detail-title">${escapeHtml(uc.name)}</h3>
      <p class="hint">In ${escapeHtml(parentDomain.name)}</p>
      <div class="tax-tagged-list" id="taxTaggedList"><p class="hint">Loading tagged prompts…</p></div>
      <button class="btn btn-ghost" id="taxTagMoreBtn"><span class="material-symbols-outlined">add</span> Tag more prompts</button>
      <div id="taxTagPicker" hidden></div>`;
        try {
            const tagged = await api(`/taxonomy/use-cases/${uc.id}/prompts`);
            const listEl = $('#taxTaggedList');
            if (listEl) {
                listEl.innerHTML = tagged.length
                    ? tagged.map(p => `
                    <div class="tax-tagged-row" data-prompt-id="${p.id}">
                      <span class="tax-tagged-title">${escapeHtml(p.title)}</span>
                      <button class="folder-mini-btn danger" data-tax-untag="${p.id}" title="Untag"><span class="material-symbols-outlined">close</span></button>
                    </div>`).join('')
                    : '<p class="hint">No prompts tagged yet.</p>';
            }
        } catch {
            const listEl = $('#taxTaggedList');
            if (listEl) listEl.innerHTML = '<p class="hint">Couldn\'t load tagged prompts.</p>';
        }
    }

    function _taxRenderTagPicker() {
        const picker = $('#taxTagPicker');
        if (!picker) return;
        picker.innerHTML = `
      <input type="text" class="forge-input" id="taxTagPickerSearch" placeholder="Search prompts…" value="${escapeAttr(_taxState.tagPickerQuery)}" />
      <div class="tax-tag-picker-list" id="taxTagPickerList"></div>
      <button class="btn btn-accent" id="taxTagPickerApply">Tag selected</button>`;
        _taxRenderTagPickerList();
        $('#taxTagPickerSearch')?.addEventListener('input', (e) => {
            _taxState.tagPickerQuery = e.target.value;
            _taxRenderTagPickerList();
        });
        $('#taxTagPickerApply')?.addEventListener('click', async () => {
            const ids = _taxState.tagPickerSelection.slice();
            if (!ids.length) { toast('Pick at least one prompt', 'warning'); return; }
            try {
                await api('/taxonomy/bulk-tag', { method: 'POST', body: { prompt_ids: ids, use_case_id: _taxState.selectedId, action: 'add' } });
                toast(ids.length + ' prompt' + (ids.length !== 1 ? 's' : '') + ' tagged', 'success');
                _taxState.tagPickerOpen = false;
                _taxState.tagPickerSelection = [];
                await _taxRenderDetail();
            } catch {
                toast('Could not tag prompts', 'error');
            }
        });
    }

    function _taxRenderTagPickerList() {
        const list = $('#taxTagPickerList');
        if (!list) return;
        const q = _taxState.tagPickerQuery.trim().toLowerCase();
        const matches = state.prompts.filter(p => !q || (p.title || '').toLowerCase().includes(q));
        list.innerHTML = matches.slice(0, 50).map(p => `
          <label class="tax-tag-picker-row">
            <input type="checkbox" value="${p.id}" ${_taxState.tagPickerSelection.includes(p.id) ? 'checked' : ''} />
            <span>${escapeHtml(p.title)}</span>
          </label>`).join('');
        $$('#taxTagPickerList input[type="checkbox"]').forEach(el => {
            el.addEventListener('change', (e) => {
                const id = parseInt(e.target.value, 10);
                if (e.target.checked) {
                    if (!_taxState.tagPickerSelection.includes(id)) _taxState.tagPickerSelection.push(id);
                } else {
                    _taxState.tagPickerSelection = _taxState.tagPickerSelection.filter(x => x !== id);
                }
            });
        });
    }

    async function _taxAddDomain() {
        const name = prompt('Domain name:');
        if (!name || !name.trim()) return;
        try {
            await api('/taxonomy/domains', { method: 'POST', body: { name: name.trim() } });
            await _taxLoadTree();
            toast('Domain added', 'success');
        } catch {
            toast('Could not add domain', 'error');
        }
    }

    async function _taxRenameDomain(id) {
        const d = _taxState.domains.find(x => x.id === id);
        const name = prompt('Rename domain:', d ? d.name : '');
        if (!name || !name.trim()) return;
        try {
            await api(`/taxonomy/domains/${id}`, { method: 'PUT', body: { name: name.trim() } });
            await _taxLoadTree();
        } catch {
            toast('Could not rename domain', 'error');
        }
    }

    async function _taxDeleteDomain(id) {
        const d = _taxState.domains.find(x => x.id === id);
        if (!confirm(`Delete domain "${d ? d.name : ''}" and all its use-cases? This can't be undone.`)) return;
        try {
            await api(`/taxonomy/domains/${id}`, { method: 'DELETE' });
            if (_taxState.selectedType === 'domain' && _taxState.selectedId === id) {
                _taxState.selectedType = null; _taxState.selectedId = null;
            }
            await _taxLoadTree();
            await _taxRenderDetail();
            toast('Domain deleted', 'success');
        } catch {
            toast('Could not delete domain', 'error');
        }
    }

    async function _taxAddUseCase(domainId) {
        const name = prompt('Use-case name:');
        if (!name || !name.trim()) return;
        try {
            await api('/taxonomy/use-cases', { method: 'POST', body: { domain_id: domainId, name: name.trim() } });
            await _taxLoadTree();
            toast('Use-case added', 'success');
        } catch {
            toast('Could not add use-case', 'error');
        }
    }

    async function _taxRenameUseCase(id) {
        let current = '';
        for (const d of _taxState.domains) {
            const u = d.use_cases.find(x => x.id === id);
            if (u) { current = u.name; break; }
        }
        const name = prompt('Rename use-case:', current);
        if (!name || !name.trim()) return;
        try {
            await api(`/taxonomy/use-cases/${id}`, { method: 'PUT', body: { name: name.trim() } });
            await _taxLoadTree();
        } catch {
            toast('Could not rename use-case', 'error');
        }
    }

    async function _taxDeleteUseCase(id) {
        if (!confirm('Delete this use-case and untag all its prompts?')) return;
        try {
            await api(`/taxonomy/use-cases/${id}`, { method: 'DELETE' });
            if (_taxState.selectedType === 'usecase' && _taxState.selectedId === id) {
                _taxState.selectedType = null; _taxState.selectedId = null;
            }
            await _taxLoadTree();
            await _taxRenderDetail();
            toast('Use-case deleted', 'success');
        } catch {
            toast('Could not delete use-case', 'error');
        }
    }

    async function _taxAutoTagScan() {
        const modal = $('#taxAutoTagModal');
        const hint = $('#taxAutoTagHint');
        const list = $('#taxAutoTagList');
        const applyBtn = $('#taxAutoTagApplyBtn');
        if (!modal) return;
        modal.classList.add('active');
        if (applyBtn) applyBtn.disabled = true;
        if (hint) hint.textContent = 'Scanning untagged prompts\u2026';
        if (list) list.innerHTML = '';

        const useCases = [];
        _taxState.domains.forEach(d => d.use_cases.forEach(u => useCases.push({ id: u.id, name: u.name, domainName: d.name })));
        if (!useCases.length) {
            if (hint) hint.textContent = 'Add a domain and use-case first.';
            return;
        }

        const taggedIds = new Set();
        const corpora = [];
        for (const uc of useCases) {
            let taggedPrompts = [];
            try {
                taggedPrompts = await api(`/taxonomy/use-cases/${uc.id}/prompts`);
            } catch { /* score this use-case on its name alone */ }
            taggedPrompts.forEach(tp => taggedIds.add(tp.id));
            const text = uc.name + ' ' + taggedPrompts.map(tp => (tp.title || '') + ' ' + (tp.content || '')).join(' ');
            corpora.push({ uc, set: _pulseTokenSet(text) });
        }

        const candidates = [];
        state.prompts.forEach(p => {
            if (taggedIds.has(p.id)) return;
            const pSet = _pulseTokenSet((p.title || '') + ' ' + (p.content || ''));
            let best = null, bestScore = 0;
            corpora.forEach(({ uc, set }) => {
                const score = _pulseJaccard(pSet, set);
                if (score > bestScore) { bestScore = score; best = uc; }
            });
            if (best && bestScore >= 0.12) candidates.push({ prompt: p, uc: best, score: bestScore });
        });

        if (!candidates.length) {
            if (hint) hint.textContent = 'No confident matches found for untagged prompts.';
            return;
        }
        candidates.sort((a, b) => b.score - a.score);
        if (hint) hint.textContent = candidates.length + ' suggestion' + (candidates.length !== 1 ? 's' : '') + ' \u2014 review and apply.';
        if (list) {
            list.innerHTML = candidates.map(cnd => `
          <label class="tax-autotag-row">
            <input type="checkbox" checked data-pid="${cnd.prompt.id}" data-uc="${cnd.uc.id}" />
            <span class="tax-autotag-title">${escapeHtml(cnd.prompt.title || 'Untitled')}</span>
            <span class="material-symbols-outlined tax-autotag-arrow">arrow_forward</span>
            <span class="tax-autotag-target">${escapeHtml(cnd.uc.domainName)} / ${escapeHtml(cnd.uc.name)}</span>
            <span class="tax-autotag-score">${cnd.score >= 0.3 ? 'High' : 'Medium'}</span>
          </label>`).join('');
        }
        if (applyBtn) applyBtn.disabled = false;
    }

    async function _taxAutoTagApply() {
        const checked = $$('#taxAutoTagList input[type="checkbox"]:checked');
        if (!checked.length) {
            toast('Nothing selected', 'warning');
            return;
        }
        const groups = {};
        checked.forEach(cb => {
            const ucId = cb.dataset.uc;
            (groups[ucId] = groups[ucId] || []).push(parseInt(cb.dataset.pid, 10));
        });
        let taggedCount = 0, failed = 0;
        for (const [ucId, ids] of Object.entries(groups)) {
            try {
                await api('/taxonomy/bulk-tag', { method: 'POST', body: { prompt_ids: ids, use_case_id: parseInt(ucId, 10), action: 'add' } });
                taggedCount += ids.length;
            } catch {
                failed += ids.length;
            }
        }
        $('#taxAutoTagModal')?.classList.remove('active');
        if (failed) toast(taggedCount + ' tagged, ' + failed + ' failed', 'warning');
        else toast(taggedCount + ' prompt' + (taggedCount !== 1 ? 's' : '') + ' auto-tagged', 'success');
        if (_taxState.selectedType === 'usecase') await _taxRenderDetail();
    }

