    /* ============================================================================
       SURPRISE ME
       Opens a random prompt from the current filtered list. Falls back to the
       full library if no prompts match the current filter.
       ============================================================================ */
    function handleSurpriseMe() {
        let pool = state.prompts ? [...state.prompts] : [];
        if (!pool.length) {
            toast('No prompts in your library yet', 'info');
            return;
        }
        // Prefer the currently filtered/visible set if it's smaller
        const filtered = pool.filter(p => {
            if (state.filterPill) {
                const fp = state.filterPill;
                if (fp.type === 'fav' && !p.is_favorite) return false;
                if (fp.type === 'rated' && !(p.rating > 0)) return false;
                if (fp.type === 'category' && !(p.categories || []).includes(fp.value)) return false;
                if (fp.type === 'tag' && !(p.tags || []).includes(fp.value)) return false;
            }
            if (state.search) {
                const q = state.search.trim().toLowerCase();
                if (!(p.title || '').toLowerCase().includes(q) &&
                    !(p.description || '').toLowerCase().includes(q)) return false;
            }
            if (state.folderFilter) {
                if (fp?.folder_id !== state.folderFilter) return false;
            }
            return true;
        });

        const source = filtered.length ? filtered : pool;
        // Avoid showing the same prompt twice in a row
        const others = source.filter(p => p.id !== state.detailId);
        const chosen = (others.length ? others : source)[Math.floor(Math.random() * (others.length || source.length))];
        if (!chosen) return;

        // Switch to library view and open the detail panel
        if (state.view !== 'library') {
            state.view = 'library';
            $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'library'));
            const titleEl = $('#viewTitle');
            if (titleEl) titleEl.textContent = 'Library';
        }
        openDetail(chosen.id);

        // Brief flash on the card so the user can spot it
        setTimeout(() => {
            const card = $(`.prompt-card[data-id="${chosen.id}"]`);
            if (card) {
                card.scrollIntoView({
                    behavior: 'smooth',
                    block: 'nearest'
                });
                card.classList.add('surprise-flash');
                setTimeout(() => card.classList.remove('surprise-flash'), 800);
            }
        }, 120);
    }
    window.PL_surpriseMe = handleSurpriseMe;



    /* ============================================================================
       SHARED AI CALLER
       Supports OpenAI, Anthropic, Gemini. Reads provider + key from localStorage.
       callAI(systemPrompt, userMsg, maxTokens?) → Promise<string>
       ============================================================================ */
    const AI_OPENAI_COMPAT = {
        mistral:    { url: 'https://api.mistral.ai/v1/chat/completions', model: 'mistral-small-latest' },
        groq:       { url: 'https://api.groq.com/openai/v1/chat/completions', model: 'openai/gpt-oss-120b' },
        deepseek:   { url: 'https://api.deepseek.com/chat/completions', model: 'deepseek-chat' },
        xai:        { url: 'https://api.x.ai/v1/chat/completions', model: 'grok-4-latest' },
        perplexity: { url: 'https://api.perplexity.ai/chat/completions', model: 'sonar' },
    };

    async function callAI(systemPrompt, userMsg, maxTokens) {
        maxTokens = maxTokens || 1200;
        const provider = localStorage.getItem('pl_ai_provider') || 'openai';
        const apiKey = localStorage.getItem('pl_api_key_' + provider) || '';
        if (!apiKey) throw new Error('No API key — add one in Settings (⚙ bottom left)');

        if (provider === 'openai') {
            const res = await fetch('https://api.openai.com/v1/chat/completions', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': 'Bearer ' + apiKey
                },
                body: JSON.stringify({
                    model: 'gpt-5.4-mini',
                    messages: [{
                        role: 'system',
                        content: systemPrompt
                    }, {
                        role: 'user',
                        content: userMsg
                    }],
                    max_tokens: maxTokens
                }),
            });
            const data = await res.json();
            if (data.error) throw new Error(data.error.message);
            return (data.choices?.[0]?.message?.content || '').trim();

        } else if (provider === 'anthropic') {
            const res = await fetch('https://api.anthropic.com/v1/messages', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'x-api-key': apiKey,
                    'anthropic-version': '2023-06-01',
                    'anthropic-dangerous-direct-browser-access': 'true'
                },
                body: JSON.stringify({
                    model: 'claude-haiku-4-5-20251001',
                    system: systemPrompt,
                    messages: [{
                        role: 'user',
                        content: userMsg
                    }],
                    max_tokens: maxTokens
                }),
            });
            const data = await res.json();
            if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));
            return (data.content?.[0]?.text || '').trim();

        } else if (provider === 'gemini') {
            const res = await fetch('https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=' + apiKey, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    contents: [{
                        parts: [{
                            text: systemPrompt + '\n\n' + userMsg
                        }]
                    }],
                    generationConfig: {
                        maxOutputTokens: 2000
                    }
                }),
            });
            const data = await res.json();
            if (data.error) throw new Error(data.error.message);
            return (data.candidates?.[0]?.content?.parts?.[0]?.text || '').trim();

        } else if (provider === 'openrouter') {
            const model = localStorage.getItem('pl_openrouter_model') || 'openai/gpt-5.4-mini';
            const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': 'Bearer ' + apiKey
                },
                body: JSON.stringify({
                    model,
                    messages: [{
                        role: 'system',
                        content: systemPrompt
                    }, {
                        role: 'user',
                        content: userMsg
                    }],
                    max_tokens: maxTokens
                }),
            });
            const data = await res.json();
            if (data.error) throw new Error(data.error.message);
            return (data.choices?.[0]?.message?.content || '').trim();

        } else if (provider === 'cohere') {
            const res = await fetch('https://api.cohere.com/v2/chat', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': 'Bearer ' + apiKey
                },
                body: JSON.stringify({
                    model: 'command-a-03-2025',
                    messages: [{
                        role: 'system',
                        content: systemPrompt
                    }, {
                        role: 'user',
                        content: userMsg
                    }],
                    max_tokens: maxTokens
                }),
            });
            const data = await res.json();
            if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));
            const parts = data.message?.content || [];
            return parts.map(p => p.text || '').join('').trim();

        } else if (AI_OPENAI_COMPAT[provider]) {
            const cfg = AI_OPENAI_COMPAT[provider];
            const res = await fetch(cfg.url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': 'Bearer ' + apiKey
                },
                body: JSON.stringify({
                    model: cfg.model,
                    messages: [{
                        role: 'system',
                        content: systemPrompt
                    }, {
                        role: 'user',
                        content: userMsg
                    }],
                    max_tokens: maxTokens
                }),
            });
            const data = await res.json();
            if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));
            return (data.choices?.[0]?.message?.content || '').trim();

        } else {
            // Azure OpenAI or a custom-added provider — both need a stored
            // endpoint URL since there's no single well-known base URL.
            const baseUrl = localStorage.getItem('pl_base_url_' + provider) || '';
            if (!baseUrl) throw new Error(`No endpoint URL set for "${provider}" — add one in Settings`);
            const isAzure = provider === 'azure_openai';
            const headers = {
                'Content-Type': 'application/json'
            };
            if (isAzure) headers['api-key'] = apiKey;
            else headers['Authorization'] = 'Bearer ' + apiKey;
            const model = localStorage.getItem('pl_model_' + provider) || '';
            const res = await fetch(baseUrl, {
                method: 'POST',
                headers,
                body: JSON.stringify({
                    ...(model ? { model } : {}),
                    messages: [{
                        role: 'system',
                        content: systemPrompt
                    }, {
                        role: 'user',
                        content: userMsg
                    }],
                    max_tokens: maxTokens
                }),
            });
            const data = await res.json();
            if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));
            return (data.choices?.[0]?.message?.content || '').trim();
        }
    }

